package com.az.scicalc;
import android.widget.*;
import java.util.*;

/** Function selectors share the calculator's textured, numbered list surface. */
final class FunctionMenus {
 static void matrix(MainActivity app){ToolPage p=page(app,"矩阵",400,1820);p.frame();
  p.listRow("1 ","插入矩阵","最大尺寸为 7x7","info",()->MatrixSizeDialog.show(app,(rows,cols)->app.workbench.insert(()->app.formula.grid(rows,cols,false))),()->app.workbench.functionHelp(new MathFunctions.Entry("linear algebra","Matrix","最大尺寸为 7x7","matrix")));
  String[] names={"Det","Inverse","MatrixRank","Transpose","IdentityMatrix","RowReduce","CharacteristicPolynomial","Diagonal","DiagonalMatrix","Eigenvalues","Eigenvectors","LeastSquares","LinearSolve","LUDecomposition","NullSpace","PseudoInverse","SingularValueDecomposition"},params={"matrix","matrix","matrix","matrix","dimension","matrix","matrix, var","list","list","matrix","matrix","matrix, right","matrix, right","matrix","matrix","matrix","matrix"},descriptions={"计算行列式。","计算矩阵的逆矩阵","返回 matrix 的秩","求矩阵的转置。","返回单位矩阵。","返回化简行阶梯形（RREF）形式。","计算 matrix 关于变量 var 的特征多项式","计算 matrix 的对角向量","给出一个矩阵，其对角线上是 list 的值，其余位置为零。","获取 matrix 的数值特征值","获取 matrix 的数值特征向量","求解线性最小二乘问题 'matrix . x = right'。","求解线性方程组 'matrix . x = right'，并返回一个对应的解 x。","计算方阵 matrix 的 LUP 分解","返回构成 matrix 零空间（核）的向量列表","计算 matrix 的 Moore-Penrose 伪逆。如果 matrix 可逆，则伪逆等于其逆矩阵","计算 matrix 的奇异值分解"};
  for(int i=0;i<names.length;i++){final String name=names[i],parameter=params[i],description=descriptions[i];TextView row=p.listRow((i+2)+" ",name+"("+parameter+")",description,"info",()->app.workbench.insert(()->app.formula.template("func",name)),()->app.workbench.functionHelp(new MathFunctions.Entry("linear algebra",name,description,parameter)));row.setTypeface(UiFonts.MONO);}
  app.menuTools.show(p);
 }
 static ToolPage page(MainActivity app,String name,float top,float bottom){ToolPage p=new ToolPage(app,name,app.menuTools::back);p.embedded(top,bottom);return p;}
 static void trig(MainActivity app,int tab){ToolPage p=page(app,"双曲函数",880,2358);p.tabs(new String[]{"双曲函数","三角函数"},tab,i->{app.menuTools.home();trig(app,i);});String[] names=tab==0?new String[]{"Sinh","Cosh","Tanh","Coth","Sech","Csch","ArcSinh","ArcCosh","ArcTanh","ArcCoth","ArcSech","ArcCsch"}:new String[]{"Sin","Cos","Tan","Cot","Sec","Csc","ArcSin","ArcCos","ArcTan","ArcCot","ArcSec","ArcCsc"};String[] chinese={"正弦","余弦","正切","余切","正割","余割"};for(int i=0;i<names.length;i++){final String fn=names[i],description=(i>=6?"反":"")+(tab==0?"双曲":"")+chinese[i%6];TextView row=p.listRow(""+(i+1),fn+"(value)",description,"info",()->app.workbench.insert(()->app.formula.template("func",fn)),()->app.workbench.functionHelp(new MathFunctions.Entry("arith",fn,description,"value")));row.setTypeface(UiFonts.MONO);}app.menuTools.show(p);}
 static void complex(MainActivity app){ToolPage p=page(app,"复数",580,2020);String[] names={"Arg","Conjg","Re","Im","▶r∠φ","▶a+bi","Abs"},descriptions={"复数的辐角","复数的共轭","实部","虚部","以极坐标形式显示结果。","以直角坐标形式显示结果。","返回模（绝对值）。"},functions={"Arg","Conjg","Re","Im","","","Abs"};for(int i=0;i<names.length;i++){final int n=i;TextView row=p.listRow(""+(i+1),names[i],descriptions[i],"",()->{if(n==4||n==5){app.menuTools.home();complexResult(app,n==4);}else app.workbench.insert(()->app.formula.template("func",functions[n]));},null);row.setTypeface(UiFonts.MONO);}app.menuTools.show(p);}
 static void complexResult(MainActivity app,boolean polar){String source=app.formula.empty()?app.exact:app.vars(app.formula.source(app.angleMode));if(source.isEmpty()){app.toast("先输入复数表达式");return;}app.task(()->{String z=app.engine.evaluate(source,false);if(!polar)return app.engine.evaluate("ComplexExpand("+z+")",false);String radius=app.engine.evaluate("Abs("+z+")",false),angle=app.engine.evaluate("Arg("+z+")"+(app.angleMode==0?"*180/Pi":app.angleMode==2?"*200/Pi":""),false);return radius+"∠("+angle+")";},value->{app.view.result=value;app.view.invalidate();app.save();});}
 static String distributionSignature(MathFunctions.Entry e){switch(e.name){case "normalpdf":return "normalpdf(x[,mean,sigma])";case "normalcdf":return "normalcdf(lowerbound,upperbound[, mean, sigma])";case "invNorm":return "invNorm(area[,mean,sigma])";case "invT":return "invT(area,df)";case "tpdf":return "tpdf(x,df)";case "tcdf":return "tcdf(lowerbound,upperbound,df)";case "chi2pdf":return "χ²pdf(x,df)";case "chi2cdf":return "χ²cdf(lowerbound,upperbound,df)";case "binompdf":return "binompdf(n,p,x)";case "binomcdf":return "binomcdf(n,p,x)";case "poissonpdf":return "poissonpdf(mean,x)";case "poissoncdf":return "poissoncdf(mean,x)";default:return e.name+"("+String.join(", ",e.parameters)+")";}}
 static String distributionDescription(MathFunctions.Entry e){switch(e.name){case "normalpdf":return "正态概率密度函数";case "normalcdf":return "正态累积分布函数";case "invNorm":return "逆累积正态分布";case "invT":return "逆累积学生 t 分布";case "tpdf":return "学生 t 概率密度";case "tcdf":return "学生 t 分布概率";case "chi2pdf":return "卡方概率密度";default:return e.label;}}
 static void distribution(MainActivity app,int tab){ToolPage p=page(app,"分布",580,2020);p.tabs(new String[]{"DISTR","分布"},tab,i->{app.menuTools.home();distribution(app,i);});LinearLayout searchRow=new LinearLayout(app);searchRow.setGravity(android.view.Gravity.CENTER_VERTICAL);EditText search=new EditText(app);search.setTextColor(ToolPage.TEXT);search.setHintTextColor(ToolPage.TEXT);search.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,19);search.setHint("搜索");search.setSingleLine(true);search.setBackgroundColor(android.graphics.Color.TRANSPARENT);searchRow.addView(ToolPage.icon(app,"search","搜索分布",search::requestFocus,.65f),new LinearLayout.LayoutParams(p.dp(40),p.dp(44)));searchRow.addView(search,new LinearLayout.LayoutParams(0,p.dp(44),1));p.addView(searchRow,2,new LinearLayout.LayoutParams(-1,p.dp(44)));
  ArrayList<MathFunctions.Entry> entries=new ArrayList<>();if(tab==0){for(String fn:new String[]{"normalpdf","normalcdf","invNorm","invT","tpdf","tcdf","chi2pdf","chi2cdf","binompdf","binomcdf","poissonpdf","poissoncdf"})for(MathFunctions.Entry e:MathFunctions.ALL)if(e.name.equals(fn))entries.add(e);}else{entries.add(new MathFunctions.Entry("stat dist","NormalDistribution","正态分布","μ,σ"));entries.add(new MathFunctions.Entry("stat dist","StudentTDistribution","学生 t 分布","自由度"));entries.add(new MathFunctions.Entry("stat dist","ChiSquareDistribution","卡方分布","自由度"));entries.add(new MathFunctions.Entry("stat dist","BinomialDistribution","二项分布","n,p"));entries.add(new MathFunctions.Entry("stat dist","PoissonDistribution","泊松分布","λ"));entries.add(new MathFunctions.Entry("stat dist","UniformDistribution","均匀分布","{下界,上界}"));entries.add(new MathFunctions.Entry("stat dist","ExponentialDistribution","指数分布","λ"));}
  Runnable render=()->{p.body.removeAllViews();int i=1;String q=search.getText().toString().toLowerCase(Locale.ROOT);for(MathFunctions.Entry e:entries)if((e.name+e.label).toLowerCase(Locale.ROOT).contains(q)){TextView row=p.listRow(""+i++,distributionSignature(e),distributionDescription(e),"info",()->app.workbench.insert(()->app.formula.call(e.name,e.parameters.length)),()->app.workbench.functionHelp(e));row.setTypeface(UiFonts.MONO);}};Workbench.watch(search,render);render.run();app.menuTools.show(p);
 }
}
